-- Stores generated practice sentences for public.word_clean.
-- A word can have sentences generated by different models.

CREATE TABLE IF NOT EXISTS public.word_clean_sentence (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    word_clean_id bigint NOT NULL,
    word varchar(100) NOT NULL,
    model_name varchar(160) NOT NULL,
    sentence varchar(800) NOT NULL,
    sentence_translation text NOT NULL DEFAULT '',
    score integer NULL,
    score_reason text NOT NULL DEFAULT '',
    score_model_name varchar(128) NOT NULL DEFAULT '',
    scored_at timestamptz NULL
);

COMMENT ON TABLE public.word_clean_sentence IS '去重单词表的大模型造句结果';
COMMENT ON COLUMN public.word_clean_sentence.id IS 'id';
COMMENT ON COLUMN public.word_clean_sentence.word_clean_id IS 'word_clean 表 id';
COMMENT ON COLUMN public.word_clean_sentence.word IS '英文单词';
COMMENT ON COLUMN public.word_clean_sentence.model_name IS '大模型名称';
COMMENT ON COLUMN public.word_clean_sentence.sentence IS '大模型生成的例句';

ALTER TABLE public.word_clean_sentence
    ADD COLUMN IF NOT EXISTS sentence_translation text NOT NULL DEFAULT '';

COMMENT ON COLUMN public.word_clean_sentence.sentence_translation IS '大模型生成例句的中文翻译';

ALTER TABLE public.word_clean_sentence
    ADD COLUMN IF NOT EXISTS score integer NULL;

ALTER TABLE public.word_clean_sentence
    ADD COLUMN IF NOT EXISTS score_reason text NOT NULL DEFAULT '';

ALTER TABLE public.word_clean_sentence
    ADD COLUMN IF NOT EXISTS score_model_name varchar(128) NOT NULL DEFAULT '';

ALTER TABLE public.word_clean_sentence
    ADD COLUMN IF NOT EXISTS scored_at timestamptz NULL;

COMMENT ON COLUMN public.word_clean_sentence.score IS '例句质量评分，0-100 分';
COMMENT ON COLUMN public.word_clean_sentence.score_reason IS '例句质量评分原因';
COMMENT ON COLUMN public.word_clean_sentence.score_model_name IS '执行评分的大模型名称';
COMMENT ON COLUMN public.word_clean_sentence.scored_at IS '评分时间';

CREATE INDEX IF NOT EXISTS idx_word_clean_sentence_word_clean_id
    ON public.word_clean_sentence(word_clean_id);

CREATE INDEX IF NOT EXISTS idx_word_clean_sentence_word
    ON public.word_clean_sentence(word);

CREATE INDEX IF NOT EXISTS idx_word_clean_sentence_model_name
    ON public.word_clean_sentence(model_name);

CREATE INDEX IF NOT EXISTS idx_word_clean_sentence_score
    ON public.word_clean_sentence(score);

CREATE UNIQUE INDEX IF NOT EXISTS uk_word_clean_sentence_word_model
    ON public.word_clean_sentence(word_clean_id, model_name);

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'fk_word_clean_sentence_word_clean'
    ) THEN
        ALTER TABLE public.word_clean_sentence
            ADD CONSTRAINT fk_word_clean_sentence_word_clean
            FOREIGN KEY (word_clean_id)
            REFERENCES public.word_clean(id)
            ON DELETE CASCADE;
    END IF;
END $$;
